namespace Apogeu.Betting.Domain;

/// <summary>A bet as the player asked for it (<c>PlaceBet</c>, SPEC-0022 §6).</summary>
/// <param name="ClientBetId">Idempotency key generated by the client.</param>
/// <param name="Panel">Panel of the bet: 1 or 2.</param>
/// <param name="Amount">Amount, at most 2 decimal places.</param>
/// <param name="AutoCashOut">Optional automatic cash-out multiplier (executed by SPEC-0023).</param>
public sealed record BetRequest(Guid ClientBetId, int Panel, decimal Amount, decimal? AutoCashOut);
